import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.CslsFoWx.js";const n="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/01-bo-fr-clair-1280-integrite-ventes-borne.webp",o="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/01-bo-ar-clair-1280-integrite-ventes-borne.webp",i="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/01-bo-fr-sombre-1280-integrite-ventes-borne.webp",l="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/02-bo-fr-clair-1280-journal-technique-terminal.webp",d="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/03-bo-fr-clair-1280-bornes-paiements-terminal-double-paiement.webp",c="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/03-bo-fr-clair-1600-bornes-paiements-terminal-double-paiement.webp",u="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/03-bo-ar-clair-1280-bornes-paiements-terminal-double-paiement.webp",p="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/03-bo-fr-sombre-1280-bornes-paiements-terminal-double-paiement.webp",m="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/04-bo-fr-clair-1280-quarantaine-vente-hors-forme.webp",b="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/05-ios-ipad-fr-clair-paiement-verifie-impossible-verrouille.webp",g="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/05-ios-ipad-ar-sombre-paiement-verifie-impossible-verrouille.webp",v="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/05b-ios-iphone-fr-clair-liste-deja-payee.webp",h="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/06-ios-iphone-fr-clair-addition-deja-payee-sans-pastille.webp",f="/VendoraSystem-docs/captures/2026-11-21-ven108-a1-a2/07-ios-iphone-fr-clair-vente-enregistree-sans-feuille-rien-a-encaisser.webp",B=JSON.parse('{"title":"VEN-108 vagues A1 et A2 — ventes de borne hors forme, paiements au terminal : preuves sur le staging local (21/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-21-ven108-a1-a2.md","filePath":"generated/preuves/2026-11-21-ven108-a1-a2.md","lastUpdated":null}'),_={name:"preuves/2026-11-21-ven108-a1-a2.md"};function q(y,e,P,x,S,V){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ven-108-vagues-a1-et-a2-—-ventes-de-borne-hors-forme-paiements-au-terminal-preuves-sur-le-staging-local-21-11-2026" tabindex="-1">VEN-108 vagues A1 et A2 — ventes de borne hors forme, paiements au terminal : preuves sur le staging local (21/11/2026) <a class="header-anchor" href="#ven-108-vagues-a1-et-a2-—-ventes-de-borne-hors-forme-paiements-au-terminal-preuves-sur-le-staging-local-21-11-2026" aria-label="Permalink to &quot;VEN-108 vagues A1 et A2 — ventes de borne hors forme, paiements au terminal : preuves sur le staging local (21/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-21-ven108-a1-a2</code> · 0 image(s) · 0 trace(s)</p><div><p>Ticket Linear VEN-108 (spec 09 RG-KIOSK-23 et 24, spec 15 RG-FISC-69 ; fiche <code>docs/lots/VEN-108.md</code>, « Décisions prises en cours de lot »).</p><p><strong>Résultat en bref</strong> : back-office (clair, arabe, sombre), borne iPad (écran verrouillé, rendu réel des tests) et caisse iPhone faits ; <strong>Android à refaire</strong> (machine saturée, voir « Ce qui manque »).</p><p><strong>Stack</strong> : staging local <code>http://localhost:8091</code> (Flyway V135, serveur mis à jour au commit <code>d7ae4e99</code>), commerce fictif « Le Petit Bistrot (démo) ». App iOS construite depuis la copie <code>ven108-A2</code> (<code>d7ae4e99</code>, XCFramework <code>Shared</code> du 20/11 à 23:51, postérieur au dernier changement de <code>shared</code>). Back-office : Chrome headless, 1 280 px × 1,25 (1 600 px pour la capture 03 large). Aucun code de responsable ni secret visible ; les codes de test sont lus dans un fichier hors dépôt.</p><p>Les captures sont annotées (cadres orange numérotés) ; les copies sans repères sont dans <code>sans-annotation/</code>.</p><h2 id="back-office" tabindex="-1">Back-office <a class="header-anchor" href="#back-office" aria-label="Permalink to &quot;Back-office&quot;">​</a></h2><p>Données produites par des caisses virtuelles signées (clé Ed25519, outils de <code>help/tools/seed/cle_caisse.py</code>), qui poussent des événements comme les tests <code>KioskA1Ven108IntegrationTest</code> et <code>KioskA2Ven108IntegrationTest</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+n+'" alt=""></td><td><strong>Conformité fiscale › Intégrité</strong> (clé). (1) « Anomalies détectées », (2) la borne : « 2 anomalie(s) », (3) vente n° fiscal 1 avec remise : gardée, signalée « une borne n&#39;accorde pas de remise », (4) vente n° fiscal 2 <strong>à plusieurs raisons</strong> (sans commande · non payée par carte · rendu de monnaie), (5) Z n° 1 : fond de caisse à l&#39;ouverture, (6) espèces théoriques ou comptées, (7) écart de caisse. Aucun trou de numéro, chaîne « OK » pour la borne.</td></tr><tr><td><img src="'+o+'" alt=""></td><td>Même écran en arabe (page en miroir, repères à droite) : tous les libellés d&#39;anomalie sont traduits.</td></tr><tr><td><img src="'+i+'" alt=""></td><td>Même écran en thème sombre : fond d&#39;alerte et textes lisibles.</td></tr><tr><td><img src="'+l+'" alt=""></td><td><strong>Journal technique (JET)</strong>. (1) « Paiement du terminal ignoré par une caisse » (commande K-EE2, risque de double paiement), (2) « Remboursement au terminal hors vente » (K-BCB, 19,90 €, référence REMB-DEMO-01, déclaré par un responsable sous son code) ; en dessous, les trois « Paiement du terminal non enregistré » et les anomalies de scellement des ventes de borne.</td></tr><tr><td><img src="'+d+'" alt=""></td><td><strong>Bornes › Paiements au terminal à enregistrer (2)</strong> à 1 280 px. (1) titre, (2) pastille de double paiement de K-EE2 (« Encaissée aussi par une caisse qui ignorait ce paiement… : vérifiez le double paiement »), (3) K-BDF sans pastille. La pastille est tronquée à cette largeur : voir D2.</td></tr><tr><td><img src="'+c+'" alt=""></td><td>Même section à 1 600 px : la pastille de double paiement est lisible en entier, la ligne sans signal n&#39;en a pas.</td></tr><tr><td><img src="'+u+'" alt=""></td><td>Même section en arabe.</td></tr><tr><td><img src="'+p+'" alt=""></td><td>Même section en thème sombre.</td></tr><tr><td><img src="'+m+'" alt=""></td><td><strong>Synchronisation › Quarantaine</strong> : l&#39;« Addition encaissée » et le « Mouvement de stock » qui citent la vente hors forme sont retenus avec le motif « règlement ou sortie de stock d&#39;une vente de borne hors de la forme admise : la vente est gardée et signalée, un responsable décide ». (1) motif, (2) décision : Accepter / Refuser (motif obligatoire pour refuser).</td></tr></tbody></table><h2 id="borne-ipad-—-ecran-verrouille" tabindex="-1">Borne iPad — écran verrouillé <a class="header-anchor" href="#borne-ipad-—-ecran-verrouille" aria-label="Permalink to &quot;Borne iPad — écran verrouillé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+b+'" alt=""></td><td><strong>Rendu réel de <code>BornePaiementCarteTests</code></strong> (voir « Provoquer »). (1) numéro de commande, (2) montant, (3) message « Le paiement n&#39;a pas pu être vérifié. Ne payez pas une seconde fois : appelez un membre de l&#39;équipe. » ; <strong>aucun bouton</strong> (ni « Réessayer », « Payer au comptoir », « Annuler »).</td></tr><tr><td><img src="'+g+'" alt=""></td><td>Même écran en arabe, thème sombre, RTL.</td></tr></tbody></table><p><strong>Provoquer</strong> : impossible sur le staging (il faut un terminal piloté qui approuve sans numéro de transaction). Les deux images sont la vraie vue <code>PaiementCarteBorne</code> montée dans une fenêtre 1 024 × 1 366 pt (iPad Air 13&quot; M3) par le test <code>testVen108_vueReelle_ecranVerrouille_messageSansBoutons_FR_puisArabeRtlSombre</code>, dans une <strong>copie scratch</strong> du dossier <code>iosApp</code> où j&#39;ai seulement ajouté une pièce jointe d&#39;image après le rendu (le dépôt n&#39;est pas modifié). Le test a réussi. Le sélecteur de langue FR / EN / AR en bas reste sur « FR » même en arabe : artefact du test (la langue est injectée dans l&#39;environnement, pas dans le sélecteur).</p><h2 id="caisse-iphone-mode-tables" tabindex="-1">Caisse iPhone (mode Tables) <a class="header-anchor" href="#caisse-iphone-mode-tables" aria-label="Permalink to &quot;Caisse iPhone (mode Tables)&quot;">​</a></h2><p>iPhone 17 Pro Max (simulateur iOS 26.2), appairé comme caisse du staging, session ouverte par un responsable.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+v+'" alt=""></td><td>« Commandes kiosque à encaisser » : (1) K-202 avec le badge « Déjà payée au terminal ». K-BCB et K-BDF, sans ligne (données de semis minimales, 0,00 €), n&#39;ont pas le badge (voir D6).</td></tr><tr><td><img src="'+h+'" alt=""></td><td><strong>Addition K-201 déjà payée au terminal, sans pastille « Addition demandée »</strong> (le statut serveur est pourtant <code>BILL_REQUESTED</code>) : (1) seuls « Kiosque » et « À emporter » sous le titre, (2) bandeau « Déjà payée au terminal de la borne — Ne faites pas repayer le client », (3) bouton unique « Enregistrer le paiement carte · 20,50 € ».</td></tr><tr><td><img src="'+f+'" alt=""></td><td><strong>« Vente enregistrée » sans la feuille « Rien à encaisser » par-dessus</strong> (ancien défaut D1 de VEN-75 B2) : (1) confirmation, ticket, « Vente scellée — n° fiscal 1 », (2) Nouvelle vente. Deux captures prises à 4 s d&#39;écart sont identiques au pixel : rien ne la recouvre ensuite.</td></tr></tbody></table><h2 id="ce-qui-manque" tabindex="-1">Ce qui manque <a class="header-anchor" href="#ce-qui-manque" aria-label="Permalink to &quot;Ce qui manque&quot;">​</a></h2><ul><li><strong>Android (écrans 2 et 3)</strong> : « Android à refaire ». Moyenne de charge de la machine entre 250 et 700 pendant toute la session (2 000 à 2 100 processus), <code>screencap</code> adb inexploitable dans ces conditions et minuteur d&#39;inactivité de 60 s de la borne (voir les captures VEN-75 B2). Aucun émulateur n&#39;a été lancé. À refaire sur machine calme : borne tablette (écran verrouillé : impossible à provoquer, prévoir le test instrumenté équivalent), addition déjà payée sans pastille et confirmation sans double feuille sur téléphone.</li><li><strong>Écran verrouillé sur appareil</strong> : voir « Provoquer » (rendu de test, pas la borne appairée).</li><li>Le « Z de borne » n&#39;est pas montré comme écran dédié : il apparaît dans l&#39;intégrité (5, 6, 7 de la capture 01).</li></ul><h2 id="defauts-releves-a-trancher-par-le-chef-de-lot" tabindex="-1">Défauts relevés (à trancher par le chef de lot) <a class="header-anchor" href="#defauts-releves-a-trancher-par-le-chef-de-lot" aria-label="Permalink to &quot;Défauts relevés (à trancher par le chef de lot)&quot;">​</a></h2><ul><li><strong>D1 (back-office, Fiscal)</strong> : l&#39;anomalie « fond de caisse à l&#39;ouverture » du Z n° 1 apparaît deux fois (une entrée du journal à l&#39;ouverture de session, une du Z), avec le même texte.</li><li><strong>D2 (back-office, Bornes)</strong> : à 1 280 px, la pastille de double paiement (texte long sans retour à la ligne) dépasse du tableau et est coupée ; lisible dès 1 600 px.</li><li><strong>D3 (back-office, Quarantaine)</strong> : à 1 280 px, la colonne « Raison » est très haute (texte long) et le texte de la seconde ligne touche le bord de la première.</li><li><strong>D4 (iOS)</strong> : sur ce simulateur, un ancien appairage a fait planter l&#39;app au démarrage (<code>SQLiteException : no such column: local_order.terminal_paid_fact_id</code>, pile <code>OrderService.apply</code> pendant <code>SyncClient.bootstrap</code>). La colonne est pourtant ajoutée par la migration <code>72.sqm</code> : base d&#39;un build plus ancien au même numéro de version, résolu par désinstallation puis réinstallation. À vérifier côté migration (un appareil réel mis à jour depuis un build intermédiaire pourrait être concerné).</li><li><strong>D5 (semis)</strong> : mes commandes de borne K-BCB et K-BDF n&#39;ont pas de lignes (0,00 € en caisse) ; ce n&#39;est pas un défaut de l&#39;app.</li></ul><h2 id="donnees-creees-sur-le-staging-commerce-«-le-petit-bistrot-demo-»" tabindex="-1">Données créées sur le staging (commerce « Le Petit Bistrot (démo) ») <a class="header-anchor" href="#donnees-creees-sur-le-staging-commerce-«-le-petit-bistrot-demo-»" aria-label="Permalink to &quot;Données créées sur le staging (commerce « Le Petit Bistrot (démo) »)&quot;">​</a></h2><ul><li>Appareils : borne virtuelle « Borne démo (VEN-108) », caisse virtuelle « Caisse ancienne (démo) », caisse iPhone « CaisseV108 » (plus deux appairages perdus, révoqués aussitôt). <strong>Tous révoqués à la fin</strong> ; il reste actifs « Caisse comptoir (démo) » et « Caisse iPhone » (préexistants).</li><li>Chaîne fiscale de la borne virtuelle : ventes n° 1 (remise 5 %) et n° 2 (espèces, sans commande), session 1 avec fond de 100,00 € et Z n° 1 (espèces comptées 113,50 € pour 116,50 € attendus). Caisse ancienne : session ouverte (fond 150,00 €), vente n° 1 de la commande K-EE2. Caisse iPhone : session n° 1 (fond 100,00 €), vente scellée n° 1 de la commande K-201 (20,50 €).</li><li>Commandes de borne : K-EE2 (encaissée par la caisse ancienne), K-BCB (remboursée hors vente, référence REMB-DEMO-01, responsable : Sophie), K-BDF, K-201 (enregistrée en caisse), K-202 (reste à enregistrer).</li><li>Quarantaine : 2 faits en attente (Addition encaissée, Mouvement de stock), non décidés.</li><li>Les identifiants et clés des caisses virtuelles sont dans le scratchpad de la session, jamais dans le dépôt.</li></ul></div>',3)])])}const C=t(_,[["render",q]]);export{B as __pageData,C as default};
